using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
/// <summary>Document mutations shared by editor surfaces. Validate the complete document before applying it.</summary>
public static class RoadMapAuthoringOperations {
 static RoadMapLane Lane(RoadMapDocument d,string id){var l=d.lanes.FirstOrDefault(x=>x.id==id);if(l==null)throw new ArgumentException("없는 차로: "+id);return l;}
 static string Id(string prefix){return prefix+Guid.NewGuid().ToString("N");}
 static T Copy<T>(T item){return JsonUtility.FromJson<T>(JsonUtility.ToJson(item));}
 static void Heights(RoadMapLane l){if(l.heights==null||l.heights.Length!=l.points.Length)Array.Resize(ref l.heights,l.points.Length);}
 static MapPoint Point(Vector3 p){return new MapPoint{x=p.x,z=p.z};}
 public static void SetTurn(RoadMapDocument d,string laneId,int turn,bool allowed){var l=Lane(d,laneId);var ids=d.lanes.Where(n=>!n.disabled&&n.fromNode==l.toNode&&n.turn==turn&&n.change==0).Select(n=>n.id).ToArray();l.next=allowed?l.next.Concat(ids).Distinct().ToArray():l.next.Where(id=>!ids.Contains(id)).ToArray();}
 public static string Connect(RoadMapDocument d,string fromId,string targetId,int turn,int change=0){var from=Lane(d,fromId);var target=Lane(d,targetId);if(from==target||from.disabled||target.disabled)throw new ArgumentException("다른 활성 차로를 연결하세요");if(Math.Abs(turn)>1||Math.Abs(change)>1)throw new ArgumentOutOfRangeException("turn");Heights(from);Heights(target);var a=from.points.Last().V();var b=target.points[0].V();var forward=(a-from.points[from.points.Length-2].V()).normalized;var heading=(target.points[1].V()-b).normalized;float handle=Vector3.Distance(a,b)*.4f;var points=new MapPoint[33];var heights=new float[33];for(int i=0;i<33;i++){float t=i/32f,u=1-t;points[i]=Point(u*u*u*a+3*u*u*t*(a+forward*handle)+3*u*t*t*(b-heading*handle)+t*t*t*b);heights[i]=Mathf.Lerp(from.heights.Last(),target.heights[0],t);}var join=new RoadMapLane{id=Id("join:editor:"),sourceId=from.sourceId,fromNode=from.toNode,toNode=target.fromNode,ruleId=from.ruleId,number=target.number,turn=turn,change=change,points=points,heights=heights,next=new[]{target.id},status="provisional",width=from.width};d.lanes=d.lanes.Concat(new[]{join}).ToArray();from.next=from.next.Concat(new[]{join.id}).Distinct().ToArray();return join.id;}
 public static void ReverseLane(RoadMapDocument d,string id){var l=Lane(d,id);if(d.lanes.Any(n=>n.id!=Origin(l)&&Origin(n)==Origin(l)))throw new InvalidOperationException("분할 차로는 원상 복원 후 진행 방향을 바꾸세요. 정차점 거리 기준을 자동 반전할 수 없습니다.");Heights(l);Array.Reverse(l.points);Array.Reverse(l.heights);string node=l.fromNode;l.fromNode=l.toNode;l.toNode=node;l.turn=-l.turn;l.change=-l.change;l.next=new string[0];foreach(var other in d.lanes)other.next=other.next.Where(n=>n!=id).ToArray();}
 public static string DuplicateLane(RoadMapDocument d,string id){var l=Lane(d,id);var copy=Copy(l);copy.id=Id("editor:");copy.fromNode=Id("editor:start:");copy.toNode=Id("editor:end:");copy.number=l.number+1;copy.next=new string[0];copy.status="provisional";for(int i=0;i<copy.points.Length;i++){var dir=(l.points[Mathf.Min(i+1,l.points.Length-1)].V()-l.points[Mathf.Max(0,i-1)].V()).normalized;copy.points[i]=Point(l.points[i].V()+TrafficSystem.Right(dir)*l.width);}d.lanes=d.lanes.Concat(new[]{copy}).ToArray();foreach(var exit in l.next){var target=Lane(d,exit);Connect(d,copy.id,target.id,target.turn,target.change);}return copy.id;}
 public static string SplitLane(RoadMapDocument d,string id,int point){var l=Lane(d,id);if(point<=0||point>=l.points.Length-1)throw new ArgumentOutOfRangeException("point","내부 제어점에서 분할하세요");Heights(l);float cut=Length(l.points.Take(point+1).ToArray(),l.heights.Take(point+1).ToArray());var tail=Copy(l);tail.id=SegmentId(Origin(l));tail.fromNode=Id("editor:split:");tail.sourceOffset+=cut;tail.points=l.points.Skip(point).ToArray();tail.heights=l.heights.Skip(point).ToArray();l.points=l.points.Take(point+1).ToArray();l.heights=l.heights.Take(point+1).ToArray();l.toNode=tail.fromNode;l.next=new[]{tail.id};d.lanes=d.lanes.Concat(new[]{tail}).ToArray();RemapSplitReferences(d,l,tail,cut);RemapServiceBindings(d);return tail.id;}
 public static string Pocket(RoadMapDocument d,string id){var l=Lane(d,id);Heights(l);var path=new AssistedRoadNetwork.Path(l.points.Select((p,i)=>p.V(l.heights[i])).ToArray());if(path.length<65)throw new ArgumentException("65m 이상 차로가 필요합니다");var left=l.next.Select(n=>Lane(d,n)).FirstOrDefault(n=>!n.disabled&&n.turn<0&&n.change==0);if(left==null)throw new ArgumentException("좌회전 출구가 필요합니다");var original=Copy(l);float cut=path.length-55;var points=new List<MapPoint>();var values=new List<float>();Heights(l);for(float at=0;at<cut;at+=2){points.Add(Point(path.Position(at)));values.Add(path.Position(at).y);}points.Add(Point(path.Position(cut)));values.Add(path.Position(cut).y);l.points=points.ToArray();l.heights=values.ToArray();var tail=Copy(original);tail.id=SegmentId(Origin(l));tail.fromNode=Id("editor:split:");tail.sourceOffset+=cut;tail.points=Slice(path,cut,path.length);tail.heights=tail.points.Select(p=>p.elevation).ToArray();l.toNode=tail.fromNode;var pocket=Copy(tail);pocket.id=Id("editor:pocket:");pocket.toNode=Id("editor:pocket:end:");pocket.number=1;pocket.status="provisional";for(int i=0;i<pocket.points.Length;i++){float at=Mathf.Min(path.length,cut+i*2);float t=Mathf.Clamp01((at-cut)/25);pocket.points[i]=Point(path.Position(at)-TrafficSystem.Right(path.Tangent(at))*l.width*t*t*(3-2*t));}pocket.next=new string[0];l.next=new[]{tail.id,pocket.id};d.lanes=d.lanes.Concat(new[]{tail,pocket}).ToArray();RemapSplitReferences(d,l,tail,cut);RemapServiceBindings(d);Connect(d,pocket.id,left.next.Length>0?left.next[0]:left.id,-1);return pocket.id;}
 static MapPoint[] Slice(AssistedRoadNetwork.Path path,float a,float b){var p=new List<MapPoint>();for(float at=a;at<b;at+=2)p.Add(new MapPoint{x=path.Position(at).x,z=path.Position(at).z,elevation=path.Position(at).y});p.Add(new MapPoint{x=path.Position(b).x,z=path.Position(b).z,elevation=path.Position(b).y});return p.ToArray();}
 public static void DeleteLane(RoadMapDocument d,string id){var l=Lane(d,id);l.disabled=true;l.next=new string[0];foreach(var n in d.lanes)n.next=n.next.Where(x=>x!=id).ToArray();foreach(var f in d.facilities.Where(f=>f.laneId==id).ToArray())DeleteFacility(d,f.id);foreach(var p in d.signals){var removed=p.groups.Where(g=>g.laneIds.Length>0&&g.laneIds.All(x=>x==id)).Select(g=>g.id).ToArray();foreach(var g in p.groups)g.laneIds=g.laneIds.Where(x=>x!=id).ToArray();p.groups=p.groups.Where(g=>!removed.Contains(g.id)).ToArray();foreach(var stage in p.stages)stage.groups=stage.groups.Where(g=>!removed.Contains(g)).ToArray();d.facilities=d.facilities.Where(f=>f.junctionId!=p.junctionId||!removed.Contains(f.groupId)).ToArray();}RemoveEmptyPrograms(d);}
 public static void MovePoint(RoadMapDocument d,string id,int point,Vector3 pos){var lane=Lane(d,id);string node=point==0?lane.fromNode:point==lane.points.Length-1?lane.toNode:null;foreach(var l in d.lanes){Heights(l);if(l==lane){l.points[point]=Point(pos);l.heights[point]=pos.y;}if(!string.IsNullOrEmpty(node)){if(l.fromNode==node){l.points[0]=Point(pos);l.heights[0]=pos.y;}if(l.toNode==node){l.points[l.points.Length-1]=Point(pos);l.heights[l.heights.Length-1]=pos.y;}}}}
 public static void AddPoint(RoadMapDocument d,string id,int point){var l=Lane(d,id);if(point<0||point>=l.points.Length-1)throw new ArgumentOutOfRangeException("point");Heights(l);var pts=l.points.ToList();pts.Insert(point+1,Point((l.points[point].V()+l.points[point+1].V())*.5f));var h=l.heights.ToList();h.Insert(point+1,(h[point]+h[point+1])*.5f);l.points=pts.ToArray();l.heights=h.ToArray();}
 public static void DeletePoint(RoadMapDocument d,string id,int point){var l=Lane(d,id);if(point<=0||point>=l.points.Length-1)throw new ArgumentOutOfRangeException("point");Heights(l);l.points=l.points.Where((p,i)=>i!=point).ToArray();l.heights=l.heights.Where((p,i)=>i!=point).ToArray();}
 public static string CreateFacility(RoadMapDocument d,string kind,string type,Vector3 pos,string laneId=""){var l=string.IsNullOrEmpty(laneId)?null:Lane(d,laneId);var f=new RoadMapFacility{id=Id("facility:"),kind=kind,type=type,x=pos.x,z=pos.z,laneId=laneId,junctionId=l==null?"":l.ruleId,width=kind=="stopLine"?3.5f:3,length=kind=="stopLine"?.4f:2.4f};d.facilities=d.facilities.Concat(new[]{f}).ToArray();return f.id;}
 public static void DeleteFacility(RoadMapDocument d,string id){var remove=new HashSet<string>{id};bool added;do{added=false;foreach(var f in d.facilities)if(remove.Contains(f.targetId)&&remove.Add(f.id))added=true;}while(added);d.facilities=d.facilities.Where(f=>!remove.Contains(f.id)).ToArray();foreach(var p in d.signals){var groups=p.groups.Where(g=>remove.Contains(g.crosswalkId)).Select(g=>g.id).ToArray();p.groups=p.groups.Where(g=>!groups.Contains(g.id)).ToArray();foreach(var stage in p.stages)stage.groups=stage.groups.Where(g=>!groups.Contains(g)).ToArray();d.facilities=d.facilities.Where(f=>f.junctionId!=p.junctionId||!groups.Contains(f.groupId)).ToArray();}RemoveEmptyPrograms(d);}
 static void RemoveEmptyPrograms(RoadMapDocument d){var empty=d.signals.Where(p=>p.groups.Length==0).Select(p=>p.junctionId).ToArray();d.signals=d.signals.Where(p=>!empty.Contains(p.junctionId)).ToArray();d.facilities=d.facilities.Where(f=>!empty.Contains(f.junctionId)||f.kind!="vehicleSignal"&&f.kind!="pedestrianSignal").ToArray();}
 public static void SnapFacility(RoadMapDocument d,string id){var f=d.facilities.First(x=>x.id==id);var l=Lane(d,f.laneId);var end=l.points.Last().V();var dir=(end-l.points[l.points.Length-2].V()).normalized;var p=end+TrafficSystem.Right(dir)*(l.width*.5f+1);f.x=p.x;f.z=p.z;f.yaw=Quaternion.LookRotation(dir).eulerAngles.y;}
 public static string[] OpposingLanes(RoadMapDocument d,string id){var lane=Lane(d,id);var heading=(lane.points.Last().V()-lane.points[0].V()).normalized;return d.lanes.Where(l=>l!=lane&&!l.disabled&&l.change==0&&l.turn==0&&((!string.IsNullOrWhiteSpace(l.sourceId)&&l.sourceId==lane.sourceId)||(!string.IsNullOrWhiteSpace(l.roadName)&&l.roadName==lane.roadName))&&Vector3.Dot(heading,(l.points.Last().V()-l.points[0].V()).normalized)<-.8f&&Nearby(lane,l)).Select(l=>l.id).ToArray();}
 static bool Nearby(RoadMapLane a,RoadMapLane b){float threshold=Mathf.Max(12,(a.width+b.width)*1.5f);foreach(var p in a.points)for(int i=1;i<b.points.Length;i++){var start=b.points[i-1].V();var delta=b.points[i].V()-start;float t=delta.sqrMagnitude==0?0:Mathf.Clamp01(Vector3.Dot(p.V()-start,delta)/delta.sqrMagnitude);if(Vector3.Distance(p.V(),start+delta*t)<=threshold)return true;}foreach(var p in b.points)for(int i=1;i<a.points.Length;i++){var start=a.points[i-1].V();var delta=a.points[i].V()-start;float t=delta.sqrMagnitude==0?0:Mathf.Clamp01(Vector3.Dot(p.V()-start,delta)/delta.sqrMagnitude);if(Vector3.Distance(p.V(),start+delta*t)<=threshold)return true;}return false;}


 const string SegmentPrefix="editor:segment:";
 public static string Origin(RoadMapLane lane){
  if(lane==null||string.IsNullOrEmpty(lane.id))return "";
  if(!lane.id.StartsWith(SegmentPrefix,StringComparison.Ordinal))return lane.id;
  int end=lane.id.IndexOf(':',SegmentPrefix.Length);if(end<0)return lane.id;
  try{string token=lane.id.Substring(SegmentPrefix.Length,end-SegmentPrefix.Length).Replace('-','+').Replace('_','/');token=token.PadRight((token.Length+3)/4*4,'=');return System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(token));}catch(FormatException){return lane.id;}
 }
 static string SegmentId(string origin){return SegmentPrefix+Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(origin)).TrimEnd('=').Replace('+','-').Replace('/','_')+":"+Guid.NewGuid().ToString("N");}
 static float Length(MapPoint[] points,float[] heights){return new AssistedRoadNetwork.Path(points.Select((p,i)=>new Vector3(p.x,heights!=null&&i<heights.Length?heights[i]:0,p.z)).ToArray()).length;}
 static void RemapSplitReferences(RoadMapDocument d,RoadMapLane head,RoadMapLane tail,float cut){
  var additions=new List<RoadMapFacility>();
  foreach(var f in d.facilities.Where(f=>f.laneId==head.id).ToArray()){
   if(f.kind=="sign"&&f.type=="제한속도"&&f.endAt>f.startAt){
    if(f.endAt<=cut)continue;
    if(f.startAt>=cut){f.laneId=tail.id;f.startAt-=cut;f.endAt-=cut;}
    else {var copy=Copy(f);copy.id=Id("facility:");copy.laneId=tail.id;copy.startAt=0;copy.endAt-=cut;f.endAt=cut;additions.Add(copy);}
   }else f.laneId=tail.id;
  }
  d.facilities=d.facilities.Concat(additions).ToArray();
  foreach(var p in d.signals)foreach(var g in p.groups)g.laneIds=g.laneIds.Select(id=>id==head.id?tail.id:id).Distinct().ToArray();
 }
 /// <summary>Update detached full-document service distances after lane splits; never changes world positions.</summary>
 public static void RemapServiceBindings(RoadMapDocument fullDoc){
  if(fullDoc==null||fullDoc.scene==null||fullDoc.scene.objects==null)return;
  foreach(var service in fullDoc.scene.objects.Where(o=>o.IsService)){
   var current=fullDoc.lanes.FirstOrDefault(l=>l.id==service.laneId);if(current==null)continue;
   string origin=Origin(current);
   if(!fullDoc.lanes.Any(l=>l.id!=origin&&Origin(l)==origin))continue;
   float global=current.sourceOffset+service.laneAt;
   var segment=LineageSegment(fullDoc,origin,global);
   if(segment!=null){service.laneId=segment.id;service.laneAt=Mathf.Max(0,global-segment.sourceOffset);}
  }
 }
 /// <summary>Find the segment owning a global source distance. An exact split belongs to the downstream segment.</summary>
 public static RoadMapLane LineageSegment(RoadMapDocument d,string origin,float globalAt){
  var lanes=d.lanes.Where(l=>!l.disabled&&Origin(l)==origin).OrderByDescending(l=>l.sourceOffset).ToArray();
  foreach(var lane in lanes){float length=Length(lane.points,lane.heights);if(globalAt>=lane.sourceOffset-.001f&&globalAt<=lane.sourceOffset+length+.001f)return lane;}
  return null;
 }
 public static void SetOneWay(RoadMapDocument d,string laneId){foreach(var id in OpposingLanes(d,laneId))DeleteLane(d,id);}
 public static void RestoreJunction(RoadMapDocument d,RoadMapDocument baselineDoc,string junctionId){if(string.IsNullOrEmpty(junctionId))throw new ArgumentException("교차로를 선택하세요");var removed=d.lanes.Where(l=>l.ruleId==junctionId).Select(l=>l.id).ToArray();var restored=baselineDoc.lanes.Where(l=>l.ruleId==junctionId).Select(l=>Copy(l)).ToArray();var oldIds=new HashSet<string>(removed);d.lanes=d.lanes.Where(l=>!oldIds.Contains(l.id)).Concat(restored).ToArray();var valid=new HashSet<string>(d.lanes.Select(l=>l.id));foreach(var l in d.lanes){var original=baselineDoc.lanes.FirstOrDefault(x=>x.id==l.id);l.next=l.next.Where(valid.Contains).Concat(original==null?new string[0]:original.next.Where(n=>restored.Any(r=>r.id==n))).Distinct().ToArray();}foreach(var f in d.facilities.Where(f=>f.junctionId==junctionId||oldIds.Contains(f.laneId)).ToArray())DeleteFacility(d,f.id);foreach(var p in d.signals)foreach(var g in p.groups)g.laneIds=g.laneIds.Where(valid.Contains).ToArray();d.facilities=d.facilities.Concat(baselineDoc.facilities.Where(f=>f.junctionId==junctionId||restored.Any(l=>l.id==f.laneId)).Select(f=>Copy(f))).ToArray();d.signals=d.signals.Where(p=>p.junctionId!=junctionId).Concat(baselineDoc.signals.Where(p=>p.junctionId==junctionId).Select(p=>Copy(p))).ToArray();}
}
